import * as THREE from 'three';
import {OrbitControls} from 'three/addons/controls/OrbitControls.js';
const $=id=>document.getElementById(id), stage=$('stage'), load=$('loading'), place=$('place'), mode=$('mode'), detail=$('details');
const renderer=new THREE.WebGLRenderer({antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;stage.prepend(renderer.domElement);
const scene=new THREE.Scene(), camera=new THREE.PerspectiveCamera(38,1,.1,500);camera.position.set(0,-38,45);const controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.dampingFactor=.08;controls.minDistance=8;controls.maxDistance=105;controls.maxPolarAngle=Math.PI*.82;controls.target.set(0,0,0);
scene.add(new THREE.HemisphereLight(0xddeeff,0x162333,2.3));const sun=new THREE.DirectionalLight(0xfff1df,3.2);sun.position.set(-16,20,36);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-38;sun.shadow.camera.right=38;sun.shadow.camera.top=38;sun.shadow.camera.bottom=-38;sun.shadow.bias=-.0006;scene.add(sun);
const rim=new THREE.DirectionalLight(0x60b6ff,1.1);rim.position.set(18,-10,16);scene.add(rim);
const base=new THREE.Mesh(new THREE.PlaneGeometry(120,120),new THREE.MeshStandardMaterial({color:0x0d141d,roughness:1}));base.position.z=-1.0;base.receiveShadow=true;scene.add(base);
const grid=new THREE.GridHelper(100,40,0x27394b,0x1b2a38);grid.rotation.x=Math.PI/2;grid.position.z=-.98;grid.material.transparent=true;grid.material.opacity=.3;scene.add(grid);
let group=new THREE.Group();scene.add(group);let meshes=[], selected=null, rows=new Map(), homeRadius=35;const raycaster=new THREE.Raycaster(), pointer=new THREE.Vector2();const ease=()=>matchMedia('(prefers-reduced-motion: reduce)').matches?1:.14;
function clean(x){return String(x||'').trim().toUpperCase()}function number(x){return Number(x).toLocaleString('en-US')}
function polygonToShape(rings){const outer=rings[0];if(!outer||outer.length<4)return null;const shape=new THREE.Shape();outer.forEach((p,i)=>i?shape.lineTo(...project(p)):shape.moveTo(...project(p)));for(const hole of rings.slice(1)){if(hole.length<4)continue;const path=new THREE.Path();hole.forEach((p,i)=>i?path.lineTo(...project(p)):path.moveTo(...project(p)));shape.holes.push(path)}return shape}
function project(p){return [(p[0]+99.5)*.85,(p[1]-31)*1.05]}
function eachPoly(feature,fn){const g=feature.geometry;if(!g)return;if(g.type==='Polygon')fn(g.coordinates);else if(g.type==='MultiPolygon')g.coordinates.forEach(fn)}
function makeRegion(feature,name){const shapes=[];eachPoly(feature,rings=>{const s=polygonToShape(rings);if(s)shapes.push(s)});if(!shapes.length)return;const geom=new THREE.ExtrudeGeometry(shapes,{depth:.30,bevelEnabled:true,bevelSegments:1,steps:1,bevelSize:.035,bevelThickness:.035,curveSegments:1});const color=mode.value==='county'?'#293e51':'#31485d';const mesh=new THREE.Mesh(geom,[new THREE.MeshStandardMaterial({color,metalness:.25,roughness:.65,emissive:'#06111b'}),new THREE.MeshStandardMaterial({color:'#142330',metalness:.2,roughness:.7})]);mesh.castShadow=true;mesh.receiveShadow=true;mesh.userData={name,baseColor:color,level:0,target:0};group.add(mesh);meshes.push(mesh);const edges=new THREE.LineSegments(new THREE.EdgesGeometry(geom,24),new THREE.LineBasicMaterial({color:0x658096,transparent:true,opacity:.52}));mesh.add(edges);mesh.userData.edges=edges;}
function choose(name){selected=name;place.value=name;for(const mesh of meshes){const on=mesh.userData.name===name;mesh.userData.target=on?1.45:0;mesh.material[0].color.set(on?'#368cba':mesh.userData.baseColor);mesh.material[0].emissive.set(on?'#11415a':'#06111b');mesh.userData.edges.material.color.set(on?'#d7f5ff':'#658096');mesh.userData.edges.material.opacity=on?1:.4;mesh.userData.edges.material.linewidth=1;}const row=rows.get(clean(name));detail.innerHTML=row?`<div class="sub">TEXAS · OCT 23, 2026 · OFFICIAL SOS</div><h2>${name} County</h2><div class="metric">${number(row.cumulative_total)}</div><p class="muted">Cumulative early ballots · ${Number(row.cumulative_early_voting_pct).toFixed(2)}% of registered voters</p><div class="grid"><div class="cell"><small>Registered voters</small><strong>${number(row.registered_voters)}</strong></div><div class="cell"><small>In-person</small><strong>${number(row.cumulative_in_person)}</strong></div><div class="cell"><small>By mail</small><strong>${number(row.cumulative_mail)}</strong></div><div class="cell"><small>In-person Oct. 23</small><strong>${number(row.daily_in_person)}</strong></div></div><p class="notice">These are aggregate early-voting figures, not candidate results.</p>`:`<div class="sub">CONGRESSIONAL DISTRICT</div><h2>${name}</h2><p class="muted">The selected district is raised above its neighbors. Verified district-level election results have not been loaded.</p><p class="notice">We do not infer district totals from whole-county voting figures.</p>`;}
function cameraView(overhead=false){camera.position.set(0,overhead?0:-37,overhead?57:43);controls.target.set(0,0,0);controls.update()}
$('reset').onclick=()=>cameraView(false);$('top').onclick=()=>cameraView(true);$('angle').onclick=()=>cameraView(false);place.onchange=()=>choose(place.value);
const countyURL='https://cdn.jsdelivr.net/gh/plotly/datasets@master/geojson-counties-fips.json';const census='https://tigerweb.geo.census.gov/arcgis/rest/services/TIGERweb/Legislative/MapServer';
async function json(url){const r=await fetch(url);if(!r.ok)throw Error(`HTTP ${r.status}`);return r.json()}
async function districtFeatures(){const meta=await json(census+'?f=pjson');const lyr=(meta.layers||[]).find(l=>/119th Congress|119th Congressional|Congressional Districts.*119/i.test(l.name));if(!lyr)throw Error('119th congressional layer not found');const info=await json(`${census}/${lyr.id}?f=pjson`);const sf=info.fields.find(f=>/^(STATE|STATEFP|STATEFP20|STATEFP25)$/i.test(f.name));const df=info.fields.find(f=>/^(CD119|CDFP|CD|DISTRICT)$/i.test(f.name));if(!sf||!df)throw Error('Missing geographic identifiers');const params=new URLSearchParams({where:`${sf.name}='48'`,outFields:'*',outSR:'4326',returnGeometry:'true',f:'geojson'});const data=await json(`${census}/${lyr.id}/query?${params}`);return data.features.map(f=>({feature:f,name:`TX-${String(f.properties[df.name]).padStart(2,'0')}`}))}
async function show(){load.style.display='flex';load.textContent='Building dimensional geographic model…';try{const data=mode.value==='county'?(await json(countyURL)).features.filter(f=>String(f.properties.STATE)==='48').map(f=>({feature:f,name:clean(f.properties.NAME)})):await districtFeatures();if(data.length!==(mode.value==='county'?254:38))throw Error('Incomplete geographic coverage: '+data.length);scene.remove(group);group=new THREE.Group();scene.add(group);meshes=[];selected=null;data.forEach(({feature,name})=>makeRegion(feature,name));place.innerHTML='<option value="">Choose a location…</option>'+data.map(d=>d.name).sort((a,b)=>a.localeCompare(b,undefined,{numeric:true})).map(n=>`<option value="${n}">${n}</option>`).join('');detail.innerHTML='<div class="sub">SELECTED GEOGRAPHY</div><h2>Explore Texas</h2><p class="muted">Click a region or use the dropdown. Selected geography rises above the map with real extruded sidewalls and directional shadows.</p>';cameraView(false);load.style.display='none'}catch(e){load.textContent='Unable to load complete boundaries: '+e.message;console.error(e)}}
mode.onchange=show;
let down=null;renderer.domElement.addEventListener('pointerdown',e=>{down={x:e.clientX,y:e.clientY}});renderer.domElement.addEventListener('pointerup',e=>{if(!down||Math.hypot(e.clientX-down.x,e.clientY-down.y)>5)return;const rect=renderer.domElement.getBoundingClientRect();pointer.set((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1);raycaster.setFromCamera(pointer,camera);const hits=raycaster.intersectObjects(meshes,false);if(hits.length)choose(hits[0].object.userData.name);down=null});
function resize(){const w=stage.clientWidth,h=stage.clientHeight;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix()}new ResizeObserver(resize).observe(stage);resize();function tick(){requestAnimationFrame(tick);for(const mesh of meshes){const t=mesh.userData.target;mesh.userData.level+=(t-mesh.userData.level)*ease();mesh.position.z=mesh.userData.level}controls.update();renderer.render(scene,camera)}tick();
try{const r=await fetch('./counties-2026-10-23.csv');if(!r.ok)throw Error('County data missing');const lines=(await r.text()).trim().split(/\r?\n/),keys=lines.shift().split(',');for(const line of lines){const cells=line.split(',');const row=Object.fromEntries(keys.map((k,i)=>[k,cells[i]]));rows.set(clean(row.county),row)}if(rows.size!==254||[...rows.values()].reduce((n,r)=>n+Number(r.cumulative_total),0)!==3724290)throw Error('County dataset did not reconcile');await show()}catch(e){load.textContent='Unable to validate county data: '+e.message}
